@Directive({selector: '[externalDescription]'})
class ExternalDescriptionDirective {
  constructor(element: ElementRef<HTMLInputElement>) {
    element.nativeElement.setAttribute('aria-describedby', 'outside');
  }
}

@Component({
  template: `
    <span id="outside">External text</span>
    <mat-form-field>
      @if (swap) {
        <input matInput #control="matInput" externalDescription>
      } @else {
        <input matInput #control="matInput" aria-describedby="outside">
      }
      @if (swap && changeHint) {
        <mat-hint id="hint-two">Hint two</mat-hint>
      } @else {
        <mat-hint id="hint">Hint</mat-hint>
      }
    </mat-form-field>`,
})
class MatInputSwappedDescriptionControl {
  swap = false;
  changeHint = false;
  @ViewChild('control') control: MatLegacyInput;
}

describe('MatInput description ownership on control replacement', () => {
  it('retains the new control external ID when it matches the old control user ID', () => {
    const fixture = createComponent(MatInputSwappedDescriptionControl, [], [],
      [ExternalDescriptionDirective]);
    fixture.detectChanges();
    const previous = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(previous.getAttribute('aria-describedby')).toBe('outside hint');
    fixture.componentInstance.swap = true;
    fixture.componentInstance.control.stateChanges.next();
    fixture.detectChanges();
    const current = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(current).not.toBe(previous);
    expect(current.getAttribute('aria-describedby')).toBe('hint outside');
  });

  it('preserves the new control external ID when the hint also changes', () => {
    const fixture = createComponent(MatInputSwappedDescriptionControl, [], [],
      [ExternalDescriptionDirective]);
    fixture.detectChanges();
    const previous = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(previous.getAttribute('aria-describedby')).toBe('outside hint');
    fixture.componentInstance.swap = true;
    fixture.componentInstance.changeHint = true;
    fixture.componentInstance.control.stateChanges.next();
    fixture.detectChanges();
    const current = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(current).not.toBe(previous);
    expect(current.getAttribute('aria-describedby')).toBe('hint-two outside');
  });
});

@Directive({selector: '[cacheFirst]'})
class CachedInputViews implements OnChanges, OnDestroy {
  @Input() cacheFirst: TemplateRef<unknown>;
  @Input() cacheSecond: TemplateRef<unknown>;
  @Input() cacheActive = 'a';
  private readonly _views = new Map<string, EmbeddedViewRef<unknown>>();
  private _active = '';

  constructor(private _container: ViewContainerRef) {}

  ngOnChanges() {
    if (!this.cacheFirst || !this.cacheSecond || this._active === this.cacheActive) return;
    if (this._container.length) this._container.detach(0);
    let view = this._views.get(this.cacheActive);
    if (view) {
      this._container.insert(view);
    } else {
      view = this._container.createEmbeddedView(
        this.cacheActive === 'a' ? this.cacheFirst : this.cacheSecond,
      );
      this._views.set(this.cacheActive, view);
    }
    this._active = this.cacheActive;
  }

  ngOnDestroy() {
    this._views.forEach(view => view.destroy());
  }
}

@Component({
  template: `
    <mat-form-field>
      <ng-container [cacheFirst]="first" [cacheSecond]="second" [cacheActive]="which"></ng-container>
      <mat-hint [id]="hint">Hint</mat-hint>
      <ng-template #first><input matInput #control="matInput" data-name="A"></ng-template>
      <ng-template #second><input matInput #control="matInput" data-name="B"></ng-template>
    </mat-form-field>`,
})
class MatInputReusedDescriptionControl {
  which = 'a';
  hint = 'hint-a';
  @ViewChild('control') control: MatLegacyInput;
}

describe('MatInput description ownership on view reuse', () => {
  it('removes the former owned hint when a detached control is reinserted', () => {
    const fixture = createComponent(MatInputReusedDescriptionControl, [], [], [CachedInputViews]);
    fixture.detectChanges();
    const first = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(first.getAttribute('aria-describedby')).toBe('hint-a');
    fixture.componentInstance.which = 'b';
    fixture.componentInstance.hint = 'hint-b';
    fixture.componentInstance.control.stateChanges.next();
    fixture.detectChanges();
    const second = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(second).not.toBe(first);
    expect(second.getAttribute('aria-describedby')).toBe('hint-b');
    fixture.componentInstance.which = 'a';
    fixture.componentInstance.hint = 'hint-c';
    fixture.componentInstance.control.stateChanges.next();
    fixture.detectChanges();
    const again = fixture.nativeElement.querySelector('input') as HTMLInputElement;
    expect(again).toBe(first);
    expect(again.getAttribute('aria-describedby')).toBe('hint-c');
  });
});

@Component({
  template: `
    <mat-form-field><input matInput [disabled]="disabled" [readonly]="readonly"></mat-form-field>
    <mat-form-field><textarea matInput [disabled]="disabled" [readonly]="readonly"></textarea></mat-form-field>
    <mat-form-field><select matNativeControl [disabled]="disabled" [readonly]="readonly">
      <option>One</option><option>Two</option>
    </select></mat-form-field>
    <mat-form-field><input matInput [formControl]="control"></mat-form-field>
    <mat-form-field><input matInput [disabled]="disabled" aria-disabled="false"></mat-form-field>
    <mat-form-field><input matInput [disabled]="disabled" [attr.aria-disabled]="ariaDisabled"></mat-form-field>
    <mat-form-field><input matInput [disabled]="disabled" [disabledInteractive]="true"></mat-form-field>`,
})
class MatInputDisabledPeerConfig {
  control = new FormControl({value: '', disabled: true});
  ariaDisabled: string | null = 'false';
  disabled = true;
  readonly = false;
}

describe('MatInput legacy disabled behavior with current peer config', () => {
  it('keeps native controls disabled and readonly independent of interactive-disabled config', () => {
    const fixture = createComponent(MatInputDisabledPeerConfig, [
      {provide: MAT_INPUT_CONFIG, useValue: {disabledInteractive: true}},
    ]);
    fixture.detectChanges();
    const elements = Array.from(fixture.nativeElement.querySelectorAll('input, textarea, select')) as
      (HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement)[];
    expect(elements.length).toBe(7);
    elements.forEach(element => {
      expect(element.disabled).toBe(true);
      expect(element.classList.contains('mat-mdc-input-disabled-interactive')).toBe(false);
    });
    expect((elements[0] as HTMLInputElement).readOnly).toBe(false);
    expect((elements[1] as HTMLTextAreaElement).readOnly).toBe(false);
    expect(elements[0].getAttribute('aria-disabled')).toBeNull();
    expect(elements[2].getAttribute('aria-disabled')).toBeNull();
    expect(elements[4].getAttribute('aria-disabled')).toBe('false');
    expect(elements[5].getAttribute('aria-disabled')).toBe('false');
    fixture.componentInstance.ariaDisabled = 'true';
    fixture.componentInstance.disabled = false;
    fixture.componentInstance.readonly = true;
    fixture.componentInstance.control.enable();
    fixture.detectChanges();
    elements.forEach(element => expect(element.disabled).toBe(false));
    expect((elements[0] as HTMLInputElement).readOnly).toBe(true);
    expect((elements[1] as HTMLTextAreaElement).readOnly).toBe(true);
    expect(elements[2].hasAttribute('readonly')).toBe(false);
    expect(elements[4].getAttribute('aria-disabled')).toBe('false');
    expect(elements[5].getAttribute('aria-disabled')).toBe('true');
    fixture.componentInstance.ariaDisabled = null;
    fixture.detectChanges();
    expect(elements[5].getAttribute('aria-disabled')).toBeNull();
    fixture.componentInstance.control.disable();
    fixture.detectChanges();
    expect(elements[3].disabled).toBe(true);
  });
});

'[class.mat-mdc-input-disabled-interactive]': 'false',
// Preserve native disabled/readonly behavior even when the current peer enables
// interactive-disabled controls globally.
'[disabled]': 'disabled',
'[attr.readonly]': '_legacyReadonlyAttribute()',
'[attr.aria-disabled]': '_legacyAriaDisabled',

private readonly _legacyElement = inject<ElementRef<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>>(ElementRef);
/** @docs-private Host binding preserves the consumer-supplied aria-disabled value. */
protected _legacyAriaDisabled: string | null = null;

override ngDoCheck() {
  // The frozen legacy control has always been natively disabled.
  this.disabledInteractive = false;
  super.ngDoCheck();
  this._legacyAriaDisabled = this._legacyElement.nativeElement.getAttribute('aria-disabled');
}

/** @docs-private Host binding preserves the historical native readonly behavior. */
protected _legacyReadonlyAttribute(): string | null {
  return this.readonly && this._legacyElement.nativeElement.nodeName.toLowerCase() !== 'select'
    ? 'true' : null;
}

